import { tags } from "typia";

/**
 * Notification record for actions on discussion board comments. This DTO
 * represents a single notification generated by user interactions with
 * comments, such as replies, reports, or votes. Each notification is associated
 * with a specific comment and recipient, and records the nature of the
 * triggering event.
 *
 * The notification system delivers these notifications to users via email,
 * in-app alerts, or push notifications based on their preference settings. The
 * notification type indicates the action that triggered the notification
 * (reply, report, upvote, downvote), while the recipient_id is automatically
 * set to the author of the target comment and cannot be modified by clients.
 *
 * Changes to the is_read status are handled automatically by the system when
 * the user views notifications, and the timestamps are maintained by the
 * database. The most often associated operations are GET
 * /comments/{commentId}/notifications/{notificationId} for retrieval and POST
 * /comments/{commentId}/notifications for creation.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscussionBoardCommentNotification = {
  /**
   * Unique identifier for the notification record in the database. This
   * primary key allows retrieval of specific notification records by its
   * globally unique ID.
   */
  id: string & tags.Format<"uuid">;

  /**
   * The unique identifier of the comment this notification is associated
   * with. This foreign key links the notification to the original comment in
   * the discussion_board_comments table.
   */
  comment_id: string & tags.Format<"uuid">;

  /**
   * The unique identifier of the citizen who will receive this notification.
   * This is automatically set to the author of the comment and cannot be
   * modified by the client. The recipient is derived from the comment's
   * author during notification creation.
   */
  recipient_id: string & tags.Format<"uuid">;

  /**
   * The type or category of notification being triggered. This field
   * indicates the reason for the notification and is set by system events:
   * "reply" for a reply to the comment, "report" for a report on the comment,
   * "upvote" for an upvote, or "downvote" for a downvote.
   */
  type: "reply" | "report" | "upvote" | "downvote";

  /**
   * Indicates whether the notification has been read by the recipient.
   * Default is false (unread) and is automatically updated to true when the
   * user views the notification in the UI. This affects the display of unread
   * indicators in notification feeds and bell icons.
   */
  is_read: boolean;

  /**
   * Timestamp when the notification record was created in the database. This
   * field is automatically generated by the system and represents when the
   * triggering event occurred, in Asia/Seoul timezone (UTC+9).
   */
  created_at: string & tags.Format<"date-time">;
};
